// DockerServiceHandler is an implementation of the dockwell.v1.DockerService service.
type DockerServiceHandler interface {
	// GetDockerOverview counts the inventory on each selected server.
	GetDockerOverview(context.Context, *connect.Request[v1.GetDockerOverviewRequest]) (*connect.Response[v1.GetDockerOverviewResponse], error)
	// ListDockerObjects reads one bounded page of the selected inventory.
	ListDockerObjects(context.Context, *connect.Request[v1.ListDockerObjectsRequest]) (*connect.Response[v1.ListDockerObjectsResponse], error)
	// GetDockerObject reads details at one immutable Engine identity.
	GetDockerObject(context.Context, *connect.Request[v1.GetDockerObjectRequest]) (*connect.Response[v1.GetDockerObjectResponse], error)
	// PreviewDockerCleanup lists the artifacts each selected Engine can account for.
	PreviewDockerCleanup(context.Context, *connect.Request[v1.PreviewDockerCleanupRequest]) (*connect.Response[v1.PreviewDockerCleanupResponse], error)
	// PlanDockerMaintenance prepares reviewed targets or the current pause for ApplyChange.
	PlanDockerMaintenance(context.Context, *connect.Request[v1.PlanDockerMaintenanceRequest]) (*connect.Response[v1.PlanDockerMaintenanceResponse], error)
	// WatchDockerImageBuild follows one standalone build from a saved line cursor.
	// buf:lint:ignore RPC_REQUEST_RESPONSE_UNIQUE
	// buf:lint:ignore RPC_RESPONSE_STANDARD_NAME
	WatchDockerImageBuild(context.Context, *connect.Request[v1.WatchDockerImageBuildRequest], *connect.ServerStream[v1.WatchBuildResponse]) error
	// CancelDockerImageBuild asks the builder to stop before publication.
	// buf:lint:ignore RPC_REQUEST_RESPONSE_UNIQUE
	// buf:lint:ignore RPC_RESPONSE_STANDARD_NAME
	CancelDockerImageBuild(context.Context, *connect.Request[v1.CancelDockerImageBuildRequest]) (*connect.Response[v1.CancelBuildResponse], error)
	// CheckDockerNetwork validates a candidate against selected Engines.
	// REST carries the address pools in the request body.
	CheckDockerNetwork(context.Context, *connect.Request[v1.CheckDockerNetworkRequest]) (*connect.Response[v1.CheckDockerNetworkResponse], error)
	// PlanDockerNetworkAttachment records a normal workload revision for one attachment.
	PlanDockerNetworkAttachment(context.Context, *connect.Request[v1.PlanDockerNetworkAttachmentRequest]) (*connect.Response[v1.PlanDockerNetworkAttachmentResponse], error)
	// BeginDockerArtifactUpload reserves space and returns the new upload lease.
	// buf:lint:ignore RPC_REQUEST_RESPONSE_UNIQUE
	// buf:lint:ignore RPC_RESPONSE_STANDARD_NAME
	BeginDockerArtifactUpload(context.Context, *connect.Request[v1.BeginDockerArtifactUploadRequest]) (*connect.Response[v1.DockerArtifactInfo], error)
	// GetDockerArtifact reads the current lease for its creating actor and session.
	// buf:lint:ignore RPC_REQUEST_RESPONSE_UNIQUE
	// buf:lint:ignore RPC_RESPONSE_STANDARD_NAME
	GetDockerArtifact(context.Context, *connect.Request[v1.GetDockerArtifactRequest]) (*connect.Response[v1.DockerArtifactInfo], error)
	// ListDockerArtifacts lists live leases created by this actor and session on one server.
	ListDockerArtifacts(context.Context, *connect.Request[v1.ListDockerArtifactsRequest]) (*connect.Response[v1.ListDockerArtifactsResponse], error)
	// FinishDockerArtifactUpload queues validation of a completed upload.
	// buf:lint:ignore RPC_REQUEST_RESPONSE_UNIQUE
	// buf:lint:ignore RPC_RESPONSE_STANDARD_NAME
	FinishDockerArtifactUpload(context.Context, *connect.Request[v1.FinishDockerArtifactUploadRequest]) (*connect.Response[v1.DockerArtifactInfo], error)
	// AbortDockerArtifact discards the staged bytes for the selected lease.
	// buf:lint:ignore RPC_REQUEST_RESPONSE_UNIQUE
	// buf:lint:ignore RPC_RESPONSE_STANDARD_NAME
	AbortDockerArtifact(context.Context, *connect.Request[v1.AbortDockerArtifactRequest]) (*connect.Response[v1.DockerArtifactInfo], error)
	// UploadDockerArtifact appends one verified extent to an upload.
	// buf:lint:ignore RPC_REQUEST_RESPONSE_UNIQUE
	// buf:lint:ignore RPC_RESPONSE_STANDARD_NAME
	UploadDockerArtifact(context.Context, *connect.ClientStream[v1.UploadDockerArtifactRequest]) (*connect.Response[v1.DockerArtifactInfo], error)
	// DownloadDockerArtifact streams an exact extent from a sealed export.
	DownloadDockerArtifact(context.Context, *connect.Request[v1.DownloadDockerArtifactRequest], *connect.ServerStream[v1.DownloadDockerArtifactResponse]) error
	// GetDockerSettings reads the effective Engine settings and known configuration sources.
	GetDockerSettings(context.Context, *connect.Request[v1.GetDockerSettingsRequest]) (*connect.Response[v1.GetDockerSettingsResponse], error)
	// CheckDockerSettings validates proposed defaults on one server before review.
	CheckDockerSettings(context.Context, *connect.Request[v1.CheckDockerSettingsRequest]) (*connect.Response[v1.CheckDockerSettingsResponse], error)
	// PlanDockerContainerLogging reviews finite logging limits for a managed workload.
	PlanDockerContainerLogging(context.Context, *connect.Request[v1.PlanDockerContainerLoggingRequest]) (*connect.Response[v1.PlanDockerContainerLoggingResponse], error)
	// WatchDockerObjects streams invalidations and samples while a view is open.
	WatchDockerObjects(context.Context, *connect.Request[v1.WatchDockerObjectsRequest], *connect.ServerStream[v1.WatchDockerObjectsResponse]) error
}

